mapper.select:
SELECT id, name, code, is_cleared FROM stocks
WHERE code = #{code} AND board = #{board}
ORDER BY created_at DESC LIMIT 1

mapper.update:
UPDATE stocks
name = #{name}, code = #{code}, buy_date = #{buyDate}, sell_date = #{sellDate}, buy_price = #{buyPrice}, cost = #{cost}, count = #{count}, sell_price = #{sellPrice}, position = #{position}, target_profit = #{targetProfit}, profit_loss_ratio = #{profitLossRatio}, ratio_price = #{ratioPrice}, base_price = #{basePrice}, price_change_percent = #{priceChangePercent}, is_cleared = #{isCleared}, notes = #{notes}, frozen_holding_days = #{frozenHoldingDays}, top_ten_float_ratio = #{topTenFloatRatio},
WHERE id = #{id}
